/** One AAC-LC mono 44.1 kHz access unit of silence, generated by us. 1024 samples. */
export const SILENT_AAC_FRAME = Uint8Array.from([
  0xde, 0x02, 0x00, 0x4c, 0x61, 0x76, 0x63, 0x36, 0x30, 0x2e, 0x33, 0x31, 0x2e, 0x31, 0x30, 0x32, 0x00, 0x02, 0x30, 0x40, 0x0e,
]);

export const SILENT_AAC_SAMPLE_RATE = 44100;
export const SILENT_AAC_FRAME_SAMPLES = 1024;

/** AudioSpecificConfig for AAC-LC, 44.1 kHz, mono. */
export const SILENT_AAC_CONFIG = Uint8Array.from([0x12, 0x08]);

export function silentAacFrames(seconds: number): Uint8Array[] {
  const count = Math.max(1, Math.round(seconds * SILENT_AAC_SAMPLE_RATE / SILENT_AAC_FRAME_SAMPLES));
  return Array.from({ length: count }, () => SILENT_AAC_FRAME);
}
